import{c as e,ah as i,L as a,O as t}from"./chunks/framework.YKVbmyBD.js";const g=JSON.parse('{"title":"配置双系统引导","description":"","frontmatter":{},"headers":[],"relativePath":"fovlin-notes/linux-guide/configure-system/double-system-grub.md","filePath":"fovlin-notes/linux-guide/configure-system/double-system-grub.md"}'),o={name:"fovlin-notes/linux-guide/configure-system/double-system-grub.md"};function d(l,s,r,n,h,p){return i(),a("div",null,[...s[0]||(s[0]=[t('<h1 id="配置双系统引导" tabindex="-1">配置双系统引导 <a class="header-anchor" href="#配置双系统引导" aria-label="Permalink to “配置双系统引导”">​</a></h1><h2 id="配置双系统引导-1" tabindex="-1">配置双系统引导 <a class="header-anchor" href="#配置双系统引导-1" aria-label="Permalink to “配置双系统引导”">​</a></h2><p>首先确保系统中正确安装了 <code>grub</code>、<code>os-prober</code>、<code>efibootmgr</code>。</p><p>grub 的配置文件位于 <code>/etc/default/grub</code> 中，所有的配置都应在此处更改，然后更新同步到系统中。</p><p>运行 <code>sudo os-prober</code> 命令，查找其他系统的引导信息。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> os-prober</span></span></code></pre></div><p>运行 <code>sudo update-grub</code> 命令，更新 grub 引导信息。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-grub</span></span></code></pre></div><p>若系统不支持此命令，需要手动更新配置文件。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grub-makecfg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/grub/grub.cfg</span></span></code></pre></div><blockquote><p>部分发行版的 grub 命令可能是 grub2。</p></blockquote><p>若 grub 分辨率过高而引起引导界面字体过小，可以运行 <code>xrandr</code> 查看显示器支持的分辨率，并修改 <code>/etc/default/grub</code> 文件中的 <code>GRUB_GFXMODE</code> 配置项降低分辨率。</p>',12)])])}const u=e(o,[["render",d]]);export{g as __pageData,u as default};
